DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

%data = (
  20 => 1,
  24 => 2,
  26 => 5,
  30 => 7,
);
$table = "x~~ty~~n";
for (num_sort(keys %data)) {$table .= "$_~~t$data{$_}~~n"};
$x = list_random(num_sort(keys %data));
$y = $data{$x};
Context("Point");
$ans = Point($x, $y);
@b = num_sort(random_subset(2,num_sort(keys %data)));
$ans2 = abs($data{$b[0]} - $data{$b[1]});

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xlabel={\(t\) (day)},
      ylabel={\(n\) (count)},
      xmin=-1,
      xmax=31,
      ymin=0,
      ymax=10,
      xtick=,
      ytick=,
      minor xtick=,
      minor ytick=,
      clip=false,
      width=\orccaprintwidth,
      height=0.33\orccaprintwidth,
      axis line style={->},
      ]
    \addplot[soliddot] table [x=x,y=y] {
      $table
    };
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

######
# Body
######

BEGIN_PGML
Here is a graph of the number of SARS-CoV-2 (COVID) cases confirmed by the CDC within the United States during the month of January, 2020.

>> [@image(insertGraph($image_1), width=>450)@]*  <<

What are the coordinates for the data point corresponding to January [$x]th?

[_]{$ans}{5}

How many additional new cases were there between January [$b[0]]th and January [$b[1]]th?

[_]{$ans2}{5}

END_PGML

#############
# End Problem
#############

ENDDOCUMENT();
